def get_total_number_of_sequences(m, n):
    # dp[i][j] represents the number of sequences of length j with maximum value i
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(m + 1):
        for j in range(n + 1):
            if j == 0:
                dp[i][j] = 1  # One way to have a sequence of length 0 (empty sequence)
            elif i == 0:
                dp[i][j] = 0  # No way to have a sequence with max value 0 and length > 0
            elif j == 1:
                dp[i][j] = i  # All numbers from 1 to i can be the single element
            else:
                # The last element can be any number from 1 to i
                # The previous element must be <= last_element / 2
                # So we sum all dp[last_element][j-1] for last_element from 1 to i
                # But we can optimize by using the fact that the previous element must be <= i // 2
                dp[i][j] = dp[i][j-1] + dp[i // 2][j-1]
    return dp[m][n]
```

