def get_total_number_of_sequences(m, n):
    # dp[i][j] represents the number of sequences of length j where the last element is <= i
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    for i in range(1, m + 1):
        dp[i][1] = i  # sequences of length 1 can be any number from 1 to i

    for j in range(2, n + 1):
        for i in range(1, m + 1):
            # The last element can be any value from 1 to i
            # The previous element must be <= i // 2
            dp[i][j] = dp[i][j-1] + dp[i // 2][j-1]

    return dp[m][n]
