def sumofFactors(n):
    if n == 0:
        return 0
    res = 1
    # Handle even factors
    while n % 2 == 0:
        res *= 2
        n //= 2
    # Handle odd factors
    i = 3
    while i * i <= n:
        if n % i == 0:
            res *= (1 + i)
            while n % i == 0:
                n //= i
        i += 2
    # If n is a prime number greater than 2
    if n > 1:
        res *= (1 + n)
    return res
```

